import{z as m,x as B,o as t,c as l,q as r,j as s,D as n,d as e,s as o,S as i,b as E}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"随机贴现因子的深化","description":"","frontmatter":{"title":"随机贴现因子的深化","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/apt-sdf-deep.md","filePath":"econ/apt-sdf-deep.md","lastUpdated":1791063341000}'),p={name:"econ/apt-sdf-deep.md"};function d(c,a,h,f,C,D){const A=B("Mermaid");return t(),l("div",null,[a[2]||(a[2]=r('<h1 id="随机贴现因子的深化" tabindex="-1">随机贴现因子的深化 <a class="header-anchor" href="#随机贴现因子的深化" aria-label="Permalink to &quot;随机贴现因子的深化&quot;">​</a></h1><div class="epigraph"><p>所有定价模型共享同一句语法 $E[mR]=1$；模型之间的争论，从来不是要不要核，而是核在哪些状态弯曲、弯多少，以及这两问有没有独立证据。</p><footer>—— 据 Cochrane, *Asset Pricing*, 2005；Hansen and Jagannathan, *JPE* 1991 整理</footer></div><p><a href="/econ/apt-continuous-time">上一课</a>把定价收成核的随机微分方程与一行协方差开价，并给跳跃立了账。本课把这个对象推到整个课程的中枢：不进新市场，只问给定任意候选因子或模型——它作为核 \\(m\\) 的一种参数化，必须过哪几道关。离散侧的地基是<a href="/econ/stochastic-discount-factor">随机贴现因子</a>与<a href="/econ/state-price-sdf-bridge">状态价格到 SDF</a>的恒等式 \\(1=E_t[m_{t+1}R_{t+1}]\\)；本课补的是存在性与唯一性之间、约束与识别之间那些没讲透的层次。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一个恒等式不足以成为理论，缺口分三层。存在层：无套利保证存在正的 \\(m\\)（<a href="/econ/ftap">资产定价基本定理</a>），但那是「存在」，不是「这一个」——市场不完备时 \\(m\\) 不唯一（<a href="/econ/incomplete-market-pricing-bounds">不完全市场的定价界</a>），许多候选同定价而含义不同，把「能定价」读成「解释了」就记错账。约束层：\\(m\\) 的均值被无风险利率钉死，波动被可实现的最大夏普比率钉死，越界的模型不必讨论。识别层：\\(m\\) 不可观测，「因子显著」究竟是核的性质还是投影的性质，需要一套与参数化无关的度量。</p><p><span class="marginnote">数字口径：年无风险利率 4% 意味着 \\(E(m)\\approx 1/1.04\\approx 0.96\\)；市场夏普比率 0.4 到 0.5 要求 \\(\\sigma(m)\\ge 0.38\\)。CRRA 下 \\(\\sigma(m)/E(m)\\approx\\gamma\\,\\sigma(\\Delta c)\\)，而消费年波动只有 1.5% 上下，\\(\\gamma\\) 就得推到 25 以上——股权溢价之谜的全部语法就这三行算术。</span></p><p><span class="marginnote">「\\(E[mR]=1\\)」翻译成白话：把未来各状态下的收益，各乘一个「该状态的折现权重」\\(m\\) 再求平均，必须恰好等于今天的一元。\\(m\\) 大的状态就是「钱最值钱」的坏年景——能在坏年景里依然兑现的收益，才配得上高价格；模型之争全在 \\(m\\) 的形状。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三步走。第一，矩条件：把 \\(1=E[mR]\\) 沿时间向前展开，得到 \\(p_t=E_t\\big[\\sum_{s\\ge 1}m_{t+1}\\cdots m_{t+s}D_{t+s}\\big]\\)，<a href="/econ/present-value-identity">现值恒等式</a>与 <a href="/econ/campbell-shiller-decomposition">Campbell–Shiller 分解</a>都是它的展开式；<a href="/econ/lucas-tree">Lucas 树</a>与<a href="/econ/ccapm">消费 CAPM</a> 则把 \\(m\\) 钉在边际效用上。第二，界：\\(\\sigma(m)/E(m)\\) 不得小于任何可实现收益的夏普比率（Hansen–Jagannathan 1991），这是与参数化无关的<a href="/econ/hansen-jagannathan">可行域</a>；条件信息会松动无条件界（Hansen–Richard 1987），报告时必须写清用的是哪种口径。第三，参数化：因子模型就是 \\(m=a-b&#39;f\\) 的具体选择，<a href="/econ/capm-theory">CAPM 理论</a>取 \\(f\\) 为市场收益，宏观模型取消费增长；估计用 <a href="/econ/gmm-econ">GMM</a> 的矩条件，距离用核到可行集的 Hansen–Jagannathan 距离。</p>',9)),(t(),s(i,null,{default:n(()=>[o(A,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20NOARB%5B%22%E6%97%A0%E5%A5%97%E5%88%A9%22%5D%20--%3E%20EX%5B%22%E6%AD%A3%E6%A0%B8%20m%20%E5%AD%98%E5%9C%A8%22%5D%0A%20%20EX%20--%3E%20UNIQ%7B%22%E5%B8%82%E5%9C%BA%E5%AE%8C%E5%A4%87%3F%22%7D%0A%20%20UNIQ%20--%3E%7C%22%E6%98%AF%22%7C%20ONE%5B%22m%20%E5%94%AF%E4%B8%80%3A%20%E7%8A%B6%E6%80%81%E4%BB%B7%E6%A0%BC%22%5D%0A%20%20UNIQ%20--%3E%7C%22%E5%90%A6%22%7C%20MANY%5B%22m%20%E4%B8%8D%E5%94%AF%E4%B8%80%3A%20%E5%8F%AA%E5%AE%9A%E5%8C%BA%E9%97%B4%22%5D%0A%20%20EX%20--%3E%20HJ%5B%22Hansen%E2%80%93Jagannathan%20%E7%95%8C%22%5D%0A%20%20HJ%20--%3E%20PARA%5B%22%E5%9B%A0%E5%AD%90%E6%A8%A1%E5%9E%8B%20%3D%20m%20%E7%9A%84%E5%8F%82%E6%95%B0%E5%8C%96%22%5D%0A%20%20PARA%20--%3E%20REJ%7B%22%E7%95%8C%E5%86%85%E4%B8%94%E7%9F%A9%E6%9D%A1%E4%BB%B6%E8%BF%87%3F%22%7D%0A%20%20REJ%20--%3E%7C%22%E6%98%AF%22%7C%20KEEP%5B%22%E8%BF%9B%E5%85%A5%E6%9C%BA%E5%88%B6%E4%B9%8B%E4%BA%89%22%5D%0A%20%20REJ%20--%3E%7C%22%E5%90%A6%22%7C%20DROP%5B%22%E6%B7%98%E6%B1%B0%E6%88%96%E4%BF%AE%E6%AD%A3%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,[e("界为什么能当普遍记分板：它把「模型好不好」翻译成「隐含核的均值—波动对落在可行域内还是外」，"),E("a",{href:"/econ/equity-premium-puzzle"},"股权溢价之谜"),e("与"),E("a",{href:"/econ/risk-free-rate-puzzle"},"无风险利率之谜"),e("由此变成边注里那三行算术，不再依赖具体效用函数。模仿组合机制让界可操作：任意 \\(m\\) 投影到收益空间得到最小方差模仿组合，距离与资产集的选取共同决定结论。非唯一性则解释了本课程的推进方式：既然许多 \\(m\\) 同样定价，理论竞争就不在「能不能定价」，而在「弯曲发生在哪些状态、要多少风险承担、有没有定价之外的证据」——后面三课（分歧、流动性、尾部）各自给出一种弯曲方式，再后一课把弯曲者搬进主体。")],-1)),a[5]||(a[5]=E("p",null,"上一张图画候选核的审查流程；这一张拆记分板本身：两个可观测对象如何把均值—波动平面切成可行域，候选一落点便知生死。",-1)),(t(),s(i,null,{default:n(()=>[o(A,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20RF%5B%22%E6%97%A0%E9%A3%8E%E9%99%A9%E5%88%A9%E7%8E%87%204%25%22%5D%20--%3E%20PIN1%5B%22%E9%92%89%E6%AD%BB%E5%9D%87%E5%80%BC%EF%BC%9AE(m)%20%E2%89%88%200.96%22%5D%0A%20%20SR%5B%22%E5%B8%82%E5%9C%BA%E6%9C%80%E5%A4%A7%E5%A4%8F%E6%99%AE%E7%BA%A6%200.4%22%5D%20--%3E%20PIN2%5B%22%E9%92%89%E6%AD%BB%E4%B8%8B%E9%99%90%EF%BC%9A%CF%83(m)%2FE(m)%20%E2%89%A5%200.4%22%5D%0A%20%20PIN1%20--%3E%20FEAS%5B%22%E5%9D%87%E5%80%BC%E2%80%94%E6%B3%A2%E5%8A%A8%E5%B9%B3%E9%9D%A2%E4%B8%8A%E7%9A%84%E5%8F%AF%E8%A1%8C%E5%9F%9F%22%5D%0A%20%20PIN2%20--%3E%20FEAS%0A%20%20FEAS%20--%3E%20IN%5B%22%E9%9A%90%E5%90%AB%E6%A0%B8%E8%90%BD%E5%9C%A8%E5%9F%9F%E5%86%85%EF%BC%9A%E5%80%99%E9%80%89%E5%AD%98%E6%B4%BB%22%5D%0A%20%20FEAS%20--%3E%20OUT%5B%22%E8%90%BD%E5%9C%A8%E5%9F%9F%E5%A4%96%EF%BC%9A%E7%9B%B4%E6%8E%A5%E6%B7%98%E6%B1%B0%EF%BC%8C%E4%B8%8D%E5%BF%85%E8%B0%88%E6%9C%BA%E5%88%B6%22%5D%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">直觉类比：HJ 距离像「落榜距离」——把候选核投影到真实收益空间里最好的模仿组合上，量一量它离可行集还差多远；距离越短，候选越像真的。因为它与具体效用函数无关，不同门派的模型才能放在同一张记分板上比。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>HJ 界是无条件的：条件口径的放松足以救活一些在无条件检验里出局的模型，也能冤枉合格的，两种口径混用是这条路线最常见的自欺。非唯一性意味着「通过检验」只是必要条件：与消费无关的 \\(m\\) 也能定价，机制解释需要横截面之外的证据。GMM 的加权矩阵、模仿组合的资产集都会移动结论，这些自由度得登记在案——上一课程那套规范三件套在本课程照常生效。</p><p><span class="marginnote">常见误区：以为「通过 HJ 界」就等于模型被证实。界只是必要条件——与消费毫无关系的 \\(m\\) 也可能落在可行域内；过了界，机制之争才刚开场，还需要定价之外的独立证据（预期数据、微观账户、期权分布）来分胜负。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>全部定价模型共享 \\(1=E[mR]\\)；分歧只在核的弯曲位置与幅度。</li><li>完备给出唯一核，不完备只给区间；把「能定价」当「解释了」是第一类错误。</li><li>Hansen–Jagannathan 界把模型竞争翻译成均值—波动对的可行性；条件与无条件口径必须分开报。</li><li>因子模型是 \\(m\\) 的参数化；通过检验是必要条件，机制之争从本课之后才开场。</li><li>出处：Hansen and Jagannathan, <em>JPE</em> 1991；Hansen and Richard, <em>Econometrica</em> 1987；Cochrane, <em>Asset Pricing</em>, 2005。</li></ul>',6))])}const _=m(p,[["render",d]]);export{F as __pageData,_ as default};
